<script lang="ts">import{defineComponent}from"vue";import{useAdmConsolePage}from"../../app/useAdmConsolePage";export default defineComponent({setup(){return useAdmConsolePage()},name:"WorkersPage",computed:{workers(){return this.batchResult?.workers||this.batchResult?.workerItems||[]},locks(){return this.batchResult?.locks||[]},ghosts(){return this.batchResult?.ghostCandidates||[]}}});</script><template><div class="cpf-page"><div class="cpf-page-heading"><div><p class="eyebrow">AGENT / WORKER</p><h2>Worker 운영</h2><p>Worker heartbeat·lease·lock·ghost 후보를 Batch 실행과 분리해 관제합니다.</p></div><button class="ghost" @click="loadBatch">새로고침</button></div><section class="cpf-kpi-grid"><div class="cpf-stat-card"><span class="label">Workers</span><strong class="value">{{workers.length}}</strong></div><div class="cpf-stat-card"><span class="label">Locks</span><strong class="value">{{locks.length}}</strong></div><div class="cpf-stat-card"><span class="label">Ghost 후보</span><strong class="value">{{ghosts.length}}</strong></div></section><section class="cpf-card"><div class="cpf-card-head"><h2>Worker 상태</h2></div><div class="table-wrap"><table><thead><tr><th>Worker</th><th>Instance</th><th>Status</th><th>Heartbeat</th><th>Lease</th></tr></thead><tbody><tr v-for="w in workers" :key="String(w.workerId||w.instanceId)"><td>{{w.workerId}}</td><td>{{w.instanceId||w.workerInstanceId}}</td><td>{{w.status||w.workerStatus}}</td><td>{{w.lastHeartbeatAt||w.heartbeatAt}}</td><td>{{w.leaseUntil||w.leaseExpiresAt}}</td></tr></tbody></table></div><p v-if="!workers.length" class="cpf-empty">Worker 조회 결과가 없습니다.</p></section></div>
  <section class="panel route-operation-panel"><h3>Runtime Instance</h3><button type="button" @click="loadBatchRuntimeInstances">Runtime Instance 조회</button></section>
</template>